    21	        for (int i = 0; i <= n - m; i++) {
    22	            if (patHash == txtHash && matchesAt(text, pattern, i)) {
    23	                result.add(i);
    24	            }
    25	            if (i < n - m) {
    26	                txtHash = hashCalculator.roll(txtHash, text.charAt(i), text.charAt(i + m), h);
    27	            }
    28	        }
    29	        return result;
    30	    }
